from cart_station_nes_mappers import MapperReader
from test_cart_station import Wire


def fixture(prg_size=32768, chr_size=16384, name='Synthetic 87', variation=0):
    prg = b''.join(bytes((128 + bank,)) * 16384 for bank in range(prg_size // 16384))
    chr_data = b''.join(bytes((bank + variation,)) * 8192 for bank in range(chr_size // 8192))
    header = bytearray(b'NES\x1a' + bytes(12))
    header[4:8] = bytes((prg_size // 16384, chr_size // 8192, 0x70, 0x58))
    sha = lambda value: hashlib.sha1(value).hexdigest()
    profile = Profile.parse(dict(id=name, title=name, mapper=87, submapper=0,
        prg_size=prg_size, chr_size=chr_size, header=header.hex(),
        prg_sha1=sha(prg), chr_sha1=sha(chr_data), raw_sha1=sha(prg + chr_data),
        file_sha1=sha(header + prg + chr_data), probes={'first1k_sha1': sha(prg[:1024])}))
    return profile, prg, chr_data


class Cartridge87:
    def __init__(self, prg, chr_data, lower=None):
        self.prg, self.chr = prg, chr_data
        self.lower = bytes(range(256)) * 32 if lower is None else lower
        self.bank = 0
        self.events, self.modes = [], []

    def status(self):
        return 3

    def mode(self, value):
        self.modes.append(value)

    def memory(self, command, address, size):
        self.events.append(('read', command, address, size))
        if command == 0x11:
            if 0x6000 <= address < 0x8000:
                return self.lower[address - 0x6000:address - 0x6000 + size]
            offset = (address - 0x8000) % len(self.prg)
            return self.prg[offset:offset + size]
        if command == 0x13:
            # Board wiring swaps the two latched CHR address bits.
            bank = ((self.bank & 1) << 1) | ((self.bank & 2) >> 1)
            offset = (bank % (len(self.chr) // 8192)) * 8192 + address
            return self.chr[offset:offset + size]
        raise AssertionError('Unexpected command')

    def mapper87_register(self, address, value):
        assert 0x6000 <= address <= 0x7fff and 0 <= value <= 3
        self.events.append(('write', address, value))
        self.bank = value

    def cpu_register_write(self, *args, **kwargs):
        raise AssertionError('Mapper 87 must not use the general register writer')

    nes = property(lambda self: self)
    write = NesRegisters.write


@patch('cart_station_nes_mappers.time.sleep')
class Mapper87Tests(unittest.TestCase):
    def test_all_supported_geometries_two_fresh_reads(self, sleep):
        for prg_size in (16384, 32768):
            for chr_size in (16384, 32768):
                with self.subTest(prg=prg_size, chr=chr_size):
                    profile, prg, chr_data = fixture(prg_size, chr_size)
                    bus = Cartridge87(prg, chr_data)
                    self.assertIsNone(profile.support())
                    self.assertEqual(dump_profile(bus, profile), profile.header + prg + chr_data)
                    self.assertEqual(bus.modes, [1, 0])
                    prg_reads = [e for e in bus.events if e[0:2] == ('read', 0x11) and e[2] >= 0x8000]
                    self.assertEqual(len(prg_reads), 2 * prg_size // 16384)
                    self.assertEqual(len([e for e in bus.events if e[0] == 'write']), 2 * chr_size // 8192)

    def test_chr_bit_order_and_search_addresses(self, sleep):
        profile, prg, chr_data = fixture(chr_size=32768)
        bus = Cartridge87(prg, chr_data)
        dump_profile(bus, profile)
        self.assertEqual([e for e in bus.events if e[0] == 'write'],
                         [('write', 0x6000 + value, value) for value in (0, 2, 1, 3)] * 2)
        self.assertEqual(bus.events[:2], [('read', 0x11, 0x8000, 16384), ('read', 0x11, 0xc000, 16384)])

    def test_reference_search_fallback_after_eight_blocks(self, sleep):
        profile, prg, chr_data = fixture()
        bus = Cartridge87(prg, chr_data, lower=b'\xff' * 8192)
        dump_profile(bus, profile)
        writes = [e for e in bus.events if e[0] == 'write']
        self.assertEqual(writes, [('write', 0x6000, value) for value in (0, 2)] * 2)
        searches = [e for e in bus.events if e[0:2] == ('read', 0x11) and e[2] < 0x8000]
        self.assertEqual(len(searches), 32)
        self.assertEqual([e[2] for e in searches[:8]], list(range(0x6000, 0x8000, 1024)))

    def test_wrong_prg_stops_before_any_lower_window_access(self, sleep):
        profile, prg, chr_data = fixture()
        bus = Cartridge87(b'X' + prg[1:], chr_data)
        with self.assertRaisesRegex(ProtocolError, 'PRG hash mismatch'):
            dump_profile(bus, profile)
        self.assertTrue(all(e[0] == 'read' and e[1] == 0x11 and e[2] >= 0x8000 for e in bus.events))
        self.assertEqual(bus.modes, [1, 0])

    def test_second_prg_is_reverified_before_more_writes(self, sleep):
        profile, prg, chr_data = fixture()
        bus = Cartridge87(prg, chr_data)
        def progress(stage, done, total):
            if stage == 'Read 2/2':
                bus.prg = b'X' + prg[1:]
        with self.assertRaisesRegex(ProtocolError, 'PRG hash mismatch'):
            dump_profile(bus, profile, progress)
        self.assertEqual(len([e for e in bus.events if e[0] == 'write']), 2)
        self.assertEqual(bus.modes, [1, 0])

    def test_wrong_chr_bank_is_detected(self, sleep):
        profile, prg, chr_data = fixture()
        bus = Cartridge87(prg, chr_data)
        original = bus.memory
        bus.memory = lambda cmd, address, size: chr_data[:size] if cmd == 0x13 else original(cmd, address, size)
        with self.assertRaisesRegex(ProtocolError, 'CHR hash mismatch'):
            dump_profile(bus, profile)
        self.assertEqual(bus.modes, [1, 0])

    def test_direct_chr_and_search_need_verified_prg(self, sleep):
        profile, prg, chr_data = fixture()
        bus = Cartridge87(prg, chr_data)
        reader = MapperReader(bus, profile)
        with self.assertRaisesRegex(ProtocolError, 'verified fixed PRG'):
            reader.chr_rom_bank(0, 8192)
        with self.assertRaises(ProtocolError):
            reader.search_write(0x6000, 0x7fff, 0)
        reader._mapper87_prg_verified = True
        with self.assertRaises(ProtocolError):
            reader.search_write(0x5000, 0x7fff, 0)
        self.assertEqual(bus.events, [])

    def test_transport_failure_cleans_up_without_retry(self, sleep):
        profile, prg, chr_data = fixture()
        bus = Cartridge87(prg, chr_data)
        bus.mapper87_register = Mock(side_effect=ProtocolError('USB disconnected'))
        with self.assertRaisesRegex(ProtocolError, 'USB disconnected'):
            dump_profile(bus, profile)
        bus.mapper87_register.assert_called_once()
        self.assertEqual(bus.modes, [1, 0])

    def test_unsupported_layouts_never_touch_hardware(self, sleep):
        profile, _, _ = fixture()
        for changed in (replace(profile, submapper=1), replace(profile, prg_size=65536),
                        replace(profile, chr_size=0), replace(profile, chr_size=8192),
                        replace(profile, chr_size=65536)):
            bus = Mock()
            with self.assertRaises(ProtocolError):
                dump_profile(bus, changed)
            self.assertEqual(bus.mock_calls, [])

    def test_raw_and_file_hashes_are_required(self, sleep):
        profile, prg, chr_data = fixture()
        for changed in (replace(profile, raw_sha1='0' * 40), replace(profile, file_sha1='0' * 40)):
            bus = Cartridge87(prg, chr_data)
            with self.assertRaisesRegex(ProtocolError, 'hash mismatch'):
                dump_profile(bus, changed)
            self.assertEqual(bus.modes, [1, 0])

    def test_same_geometry_candidates_resolve_by_full_hash(self, sleep):
        first, prg, _ = fixture(name='First')
        second, _, chr_data = fixture(name='Second', variation=20)
        selected, payload = dump_candidates(Cartridge87(prg, chr_data), (first, second))
        self.assertEqual(selected, second)
        self.assertEqual(payload, second.header + prg + chr_data)

    def test_all_ten_db_profiles_readable(self, sleep):
        profiles = [p for p in Database.load(data('nes_profiles.reference.json')).profiles if p.mapper == 87]
        self.assertEqual(len(profiles), 10)
        self.assertTrue(all(p.support() is None for p in profiles))
        kage = [p for p in profiles if p.title == 'Kage no Densetsu (Japan).nes']
        self.assertEqual(len(kage), 1)
        self.assertEqual((kage[0].prg_size, kage[0].chr_size), (32768, 16384))

    def test_service_saves_and_reuses_verified_file(self, sleep):
        profile, prg, chr_data = fixture()
        with tempfile.TemporaryDirectory() as folder:
            service = Service(Path(folder), database=Database([profile]))
            service.adapter = Cartridge87(prg, chr_data)
            service.profile, service.selected_id, service.candidate = profile, profile.id, 3
            with patch('cart_station_service.identify', return_value=(profile,)):
                path, created = service.capture(lambda *args: None)
                self.assertTrue(created)
                self.assertEqual(path.read_bytes(), profile.header + prg + chr_data)
                self.assertFalse(service.capture(lambda *args: None)[1])

    def test_cancel_before_second_read_saves_nothing(self, sleep):
        profile, prg, chr_data = fixture()
        with tempfile.TemporaryDirectory() as folder:
            destination = Path(folder) / 'output'
            service = Service(destination, database=Database([profile]))
            bus = Cartridge87(prg, chr_data)
            service.adapter, service.profile, service.selected_id, service.candidate = bus, profile, profile.id, 3
            def cancel(stage, done, total):
                if stage == 'Read 2/2':
                    raise UserCancelled('Cancelled')
            with patch('cart_station_service.identify', return_value=(profile,)):
                with self.assertRaises(UserCancelled):
                    service.capture(cancel)
            self.assertFalse(destination.exists())
            self.assertEqual(bus.modes, [1, 0])


class Mapper87WireTests(unittest.TestCase):
    def test_scoped_writer_sends_reference_command_and_two_acks_without_dummy(self):
        wire = Wire(bytes(16), fragment=3)
        Adapter(wire).nes.mapper87_register(0x6002, 2)
        self.assertEqual(wire.writes, [packet(0x12, 8, 1, 0x6002, 1), b'\x02'])
        self.assertFalse(wire.replies)

    def test_general_guard_unchanged_and_scoped_guard_is_strict(self):
        wire = Wire(b'')
        adapter = Adapter(wire)
        for address, value in ((0x5fff, 0), (0x8000, 0), (True, 0), (0x6000, True),
                               (0x6000, 4), (0x6000, -1)):
            with self.assertRaises(ValueError):
                adapter.nes.mapper87_register(address, value)
        with self.assertRaises(ValueError):
            adapter.nes.cpu_register_write(0x6000, 0)
        self.assertEqual(wire.writes, [])


if __name__ == '__main__':
    unittest.main()
